import pandas as pd
from pathlib import Path
import math

def stats(file_path):
  try:
    df = pd.read_csv(file_path)
    numeric_cols = df.select_dtypes(include=[int, float]).columns
    stats_list = []
    for col in numeric_cols:
      mean = math.avg(df[col])
      median = math.median(df[col])
      min_val = math.min(df[col])
      max_val = math.max(df[col])
      std_dev = math.std(df[col])
      stats_list.append((col, mean, median, min_val, max_val, std_dev))
    print(pd.DataFrame(stats_list, columns=['Column', 'Mean', 'Median', 'Min', 'Max', 'Std Dev']))
  except FileNotFoundError:
    print(f'Error: File not found at path: {file_path}')
  except pd.errors.EmptyDataError:
    print(f'Error: File at path: {file_path} is empty')
  except pd.errors.ParserError:
    print(f'Error: Non-numeric data in file at path: {file_path}')

def main():
  if __name__ == '__main__':
    file_path = Path("./csv_stats.py").parent / "data.csv"
